#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

ROOT=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd)
WORKER_DIR="$ROOT/worker"
WORKER_CONFIG="$WORKER_DIR/wrangler.toml"
ENV_FILE=/dev/null
WRANGLER_LOGIN_CREATED=0

if [[ ! -f "$WORKER_DIR/docs-editor.mjs" || ! -f "$WORKER_CONFIG" ]]; then
  printf 'Run this wizard from a checkout that contains worker/docs-editor.mjs and worker/wrangler.toml.\n' >&2
  exit 1
fi
if [[ ! -t 0 ]]; then
  printf 'This wizard needs an interactive terminal because it accepts credentials.\n' >&2
  exit 1
fi
for command_name in npx openssl curl awk grep mktemp mv rm; do
  if ! command -v "$command_name" >/dev/null 2>&1; then
    printf 'Required command not found: %s\n' "$command_name" >&2
    exit 1
  fi
done

wrangler() {
  npx --yes wrangler@latest "$@"
}

put_secret() {
  local name="$1" value="$2"
  printf '%s' "$value" | wrangler secret put "$name"
}

cleanup_wrangler_login() {
  if (( WRANGLER_LOGIN_CREATED )); then
    wrangler logout >/dev/null 2>&1 || true
  fi
}
trap cleanup_wrangler_login EXIT

TOTAL_STAGES=7

banner "Configurar PRs de documentação"

stage "GitHub App"
say "Cria uma GitHub App em nome da organização GalaxyHaze, ou abre uma App existente."
open_url "https://github.com/organizations/GalaxyHaze/settings/apps"
step "Define Homepage URL como https://zith-lang.org."
step "Define User authorization callback URL como https://docs-api.zith-lang.org/auth/callback."
step "Mantém a autorização automática durante a instalação desativada."
step "Em Repository permissions, define Contents e Pull requests como Read and write."
step "Não são necessários webhooks. Guarda a App e gera um Client secret na página da App."
pause "Quando tiveres a App ID, Client ID e Client secret, continua."
ask GITHUB_APP_ID "App ID:"
ask GITHUB_CLIENT_ID "Client ID:"
ask_secret GITHUB_CLIENT_SECRET "Client secret:"
if [[ ! "$GITHUB_APP_ID" =~ ^[0-9]+$ || -z "$GITHUB_CLIENT_ID" || -z "$GITHUB_CLIENT_SECRET" ]]; then
  printf 'App ID, Client ID e Client secret são obrigatórios; volta a executar o wizard.\n' >&2
  exit 1
fi

stage "Instalar a GitHub App"
say "Instala a App apenas nos repositórios necessários."
open_url "https://github.com/organizations/GalaxyHaze/settings/apps"
step "Abre Install App, instala em GalaxyHaze e seleciona apenas Zith-Lang e Zith."
step "Depois da instalação, abre Configure para essa instalação."
step "O Installation ID é o número no fim do URL da página Configure."
pause "Quando encontrares o Installation ID, continua."
ask GITHUB_INSTALLATION_ID "Installation ID:"
if [[ ! "$GITHUB_INSTALLATION_ID" =~ ^[0-9]+$ ]]; then
  printf 'Installation ID deve conter apenas dígitos; volta a executar o wizard.\n' >&2
  exit 1
fi

stage "Autenticar na Cloudflare"
say "A autenticação por código de dispositivo funciona sem browser no terminal remoto."
if wrangler whoami >/dev/null 2>&1; then
  say "Wrangler já está autenticado; será reutilizada a sessão existente."
else
  step "Abre no teu browser local o URL e introduz o código que Wrangler mostrar."
  wrangler login --device --browser=false
  WRANGLER_LOGIN_CREATED=1
fi

stage "Criar o namespace KV"
say "O Worker usa KV para sessões OAuth e limites de publicação."
if grep -Fq 'id = "REPLACE_WITH_CLOUDFLARE_KV_NAMESPACE_ID"' "$WORKER_CONFIG"; then
  if ! confirm "Criar o namespace DOCS_SESSIONS na conta Cloudflare autenticada?"; then
    printf 'Configuração cancelada antes de criar recursos Cloudflare.\n'
    exit 1
  fi
  kv_output=$(wrangler kv namespace create DOCS_SESSIONS 2>&1) || {
    printf '%s\n' "$kv_output" >&2
    exit 1
  }
  printf '%s\n' "$kv_output"
  KV_NAMESPACE_ID=""
  while IFS= read -r line; do
    if [[ "$line" =~ id[[:space:]]*=[[:space:]]*\"([[:xdigit:]]{32})\" ]]; then
      KV_NAMESPACE_ID="${BASH_REMATCH[1]}"
    fi
  done <<< "$kv_output"
  if [[ -z "$KV_NAMESPACE_ID" ]]; then
    ask KV_NAMESPACE_ID "Copia o ID de 32 caracteres mostrado acima:"
  fi
  if [[ ! "$KV_NAMESPACE_ID" =~ ^[[:xdigit:]]{32}$ ]]; then
    printf 'O ID do namespace deve conter exatamente 32 caracteres hexadecimais.\n' >&2
    exit 1
  fi
  tmp_config=$(mktemp "$WORKER_DIR/wrangler.toml.XXXXXX")
  if ! awk -v namespace_id="$KV_NAMESPACE_ID" '
    {
      gsub(/REPLACE_WITH_CLOUDFLARE_KV_NAMESPACE_ID/, namespace_id)
      print
    }
  ' "$WORKER_CONFIG" > "$tmp_config"; then
    rm -f "$tmp_config"
    exit 1
  fi
  mv "$tmp_config" "$WORKER_CONFIG"
  say "Gravado o ID do namespace em worker/wrangler.toml."
elif grep -Eq 'id = "[[:xdigit:]]{32}"' "$WORKER_CONFIG"; then
  say "worker/wrangler.toml já contém um ID KV; não será criado outro namespace."
else
  printf 'Não encontrei o placeholder nem um ID KV válido em %s.\n' "$WORKER_CONFIG" >&2
  exit 1
fi

stage "Publicar o Worker"
say "O deploy configura docs-api.zith-lang.org conforme worker/wrangler.toml."
note "A zona zith-lang.org precisa estar disponível na conta Cloudflare autenticada."
if ! confirm "Fazer deploy do Worker agora?"; then
  printf 'Deploy cancelado. O ID KV já foi gravado e será reutilizado na próxima execução.\n'
  exit 1
fi
wrangler deploy

stage "Configurar os secrets da GitHub App"
say "Cada comando envia o valor por stdin ao Wrangler; nenhum destes valores é escrito em .env."
step "GITHUB_APP_ID e GITHUB_CLIENT_ID são IDs da página General da GitHub App."
step "GITHUB_CLIENT_SECRET é o Client secret gerado na página da App."
step "GITHUB_INSTALLATION_ID é o número no URL da página Configure da instalação."
put_secret GITHUB_APP_ID "$GITHUB_APP_ID"
put_secret GITHUB_CLIENT_ID "$GITHUB_CLIENT_ID"
put_secret GITHUB_CLIENT_SECRET "$GITHUB_CLIENT_SECRET"
put_secret GITHUB_INSTALLATION_ID "$GITHUB_INSTALLATION_ID"
unset GITHUB_APP_ID GITHUB_CLIENT_ID GITHUB_CLIENT_SECRET GITHUB_INSTALLATION_ID

stage "Configurar a chave privada"
say "No computador local, converte o PEM descarregado do GitHub para PKCS#8 com:"
printf '    openssl pkcs8 -topk8 -nocrypt -in app-private-key.pem -out app-private-key-pkcs8.pem\n'
step "Abre o ficheiro convertido localmente e copia todo o bloco PEM."
step "Cola o bloco abaixo; a entrada não será mostrada. Depois escreve END numa linha própria."
PRIVATE_KEY=""
while IFS= read -r -s line; do
  if [[ "$line" == "END" ]]; then
    printf '\n'
    break
  fi
  PRIVATE_KEY+="${line}"$'\n'
  printf '\n'
done
if [[ "$PRIVATE_KEY" != *"-----BEGIN PRIVATE KEY-----"* ||
      "$PRIVATE_KEY" != *"-----END PRIVATE KEY-----"* ||
      "$PRIVATE_KEY" == *"-----BEGIN RSA PRIVATE KEY-----"* ]]; then
  printf 'Esperava uma chave PEM PKCS#8 não cifrada. Nada foi enviado; volta a executar o wizard.\n' >&2
  unset PRIVATE_KEY
  exit 1
fi
if ! printf '%s' "$PRIVATE_KEY" | openssl pkey -check -noout >/dev/null 2>&1; then
  printf 'A chave não passou a validação OpenSSL. Nada foi enviado; volta a executar o wizard.\n' >&2
  unset PRIVATE_KEY
  exit 1
fi
put_secret GITHUB_PRIVATE_KEY "$PRIVATE_KEY"
unset PRIVATE_KEY

stage "Verificar o endpoint"
say "A verificação abaixo só inicia OAuth; não cria um branch nem um PR."
if status=$(curl --silent --show-error --output /dev/null --write-out '%{http_code}' \
  "https://docs-api.zith-lang.org/auth/start?return=https%3A%2F%2Fzith-lang.org%2Fdocs%2F") &&
  [[ "$status" == "302" ]]; then
  say "O Worker respondeu com HTTP 302 para iniciar o OAuth."
else
  warn "O endpoint não respondeu com HTTP 302. Verifica o domínio, o deploy e os secrets."
fi
if (( WRANGLER_LOGIN_CREATED )); then
  wrangler logout
  WRANGLER_LOGIN_CREATED=0
  say "A sessão Wrangler criada por este wizard foi removida."
fi
note "O Worker apenas abre PRs. Aprovação, rejeição e merge continuam manuais no GitHub."
note "A interface pública ainda precisa de Publish ligado a este Worker para os utilizadores o chamarem."

finish
